int brcms_ucode_init_uint ( struct brcms_info * wl , size_t * n_bytes , u32 idx ) { int i , entry ; const u8 * pdata ; struct firmware_hdr * hdr ; for ( i = 0 ; i < wl -> fw . fw_cnt ; i ++ ) { hdr = ( firmware_hdr * ) wl -> fw . fw_hdr [ i ] -> data ; for ( entry = 0 ; entry < wl -> fw . hdr_num_entries [ i ] ; entry ++ , hdr ++ ) { if ( le32_to_cpu ( hdr -> idx ) == idx ) { pdata = wl -> fw . fw_bin [ i ] -> data + le32_to_cpu ( hdr -> offset ) ; if ( le32_to_cpu ( hdr -> len ) != 4 ) { brcms_err ( wl -> wlc -> hw -> d11core , "ERROR: fw hdr len\n" ) ; return - ENOMSG ; } return 0 ; } } } brcms_err ( wl -> wlc -> hw -> d11core , "ERROR: ucode tag:%d can not be found!\n" , idx ) ; return - ENOMSG ; } 